style.css:
/* General Body Styles */
body {
    font-family: 'Arial', sans-serif;
    background-color: #222f3e;  /* Dark Green background */
    color: #ffffff;  /* White text */
    margin: 0;
    padding: 0;
}

/* Header Styles */
header {
    background-color: #1e2a36;  /* Slightly darker Green for the header */
    color: #ffffff;  /* White text */
    padding: 20px;
    text-align: center;
}

header h1 {
    font-size: 36px;
    font-weight: bold;
}

/* Navbar Styles */
nav {
    background-color: #44577f;  /* Medium Green for the navbar */
    text-align: center;
    padding: 10px;
}

nav a {
    color: #ffffff;
    text-decoration: none;
    margin: 0 15px;
    font-size: 18px;
}

nav a:hover {
    color: #d1e1ff;  /* Light Green when hovering */
}

/* Main Content Styles */
main {
    padding: 30px;
    background-color: #f4f4f9;  /* Light Gray background for main content */
    color: #333333;
}

main h2 {
    font-size: 28px;
    font-weight: bold;
    color: #1e2a36;  /* Dark Green for headings */
}

main p {
    font-size: 16px;
    line-height: 1.6;
}

/* Footer Styles */
footer {
    background-color: #1e2a36;  /* Dark Green footer */
    color: #ffffff;
    padding: 15px;
    text-align: center;
}

footer a {
    color: #ffffff;
    text-decoration: none;
}

footer a:hover {
    color: #d1e1ff;  /* Light Green hover effect */
}

/* Button Styles */
button {
    background-color: #3e5c7a;  /* Olive Green button background */
    color: #ffffff;
    border: none;
    padding: 10px 20px;
    font-size: 16px;
    cursor: pointer;
}

button:hover {
    background-color: #44577f;  /* Lighter Green when hovering */
}

/* Forms & Input Styles */
input, textarea {
    background-color: #ffffff;
    color: #333333;
    padding: 10px;
    border: 1px solid #ddd;
    font-size: 16px;
    width: 100%;
}

input:focus, textarea:focus {
    border-color: #3e5c7a;  /* Olive Green focus border */
    outline: none;
}

/* Links */
a {
    color: #3e5c7a;  /* Olive Green for links */
}

a:hover {
    color: #1e2a36;  /* Dark Green hover effect for links */
}

/* Responsive Design */
@media (max-width: 768px) {
    header h1 {
        font-size: 28px;
    }
    
    nav a {
        font-size: 16px;
    }

    main {
        padding: 20px;
    }
}
